use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::Datelike;
use std::collections::BTreeMap;

const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;

pub struct InvoiceMonthlyCommand;

/// Apply the invoice rule to one completed billable entry.
/// Billing is rounded up independently for each entry to the next 15-minute
/// increment; an exact increment is not increased.
fn invoice_seconds(entry: &TimeEntry) -> Option<i64> {
    if !entry.billable || entry.is_running() || entry.stop.is_none() || entry.duration < 0 {
        return None;
    }

    Some(
        ((entry.duration + BILLING_INCREMENT_SECONDS - 1) / BILLING_INCREMENT_SECONDS)
            * BILLING_INCREMENT_SECONDS,
    )
}

fn monthly_totals(entries: impl IntoIterator<Item = TimeEntry>) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        let Some(seconds) = invoice_seconds(&entry) else {
            continue;
        };
        let month = format!("{:04}-{:02}", entry.start.year(), entry.start.month());
        *totals.entry(month).or_insert(0) += seconds;
    }
    totals
}

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let totals = monthly_totals(entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = totals.values().sum();
        for (month, seconds) in totals {
            println!("{month}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

