    fn entry(start: &str, duration: i64, billable: bool, stopped: bool) -> TimeEntry {
        let start = Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap();
        TimeEntry {
            start,
            duration,
            billable,
            stop: stopped.then_some(start + chrono::Duration::seconds(duration)),
            ..TimeEntry::default()
        }
    }

    #[test]
    fn groups_completed_billable_entries_by_utc_month_and_sorts() {
        let totals = monthly_totals([
            entry("2025-02-01T00:00:00Z", 901, true, true),
            entry("2024-12-31T23:00:00Z", 900, true, true),
            entry("2025-02-15T00:00:00Z", 60, false, true),
        ]);

        assert_eq!(
            totals.into_iter().collect::<Vec<_>>(),
            vec![("2024-12".into(), 900), ("2025-02".into(), 1800)]
        );
    }

    #[test]
    fn excludes_running_entries() {
        let totals = monthly_totals([entry("2025-01-01T00:00:00Z", -1, true, false)]);
        assert!(totals.is_empty());
    }
